          "记录网站角色、读者任务、相关作品、拟议位置、地区、来源日期、公开联系路径与未确认问题。受众数据注明来源和范围，估计不写成已审计结果。研究不需要收集无关个人资料。\n\n以下为编辑假设：一个教程网站与一个优惠码网站都可能带来访问，但品牌目前要解释一项复杂安装任务。先研究哪一方能完成相关解释，以及所需资料和内容工作，而不是只按访问总量选择。\n\nQuickKOL 可以帮助理解内容任务、研究相关创作者作品并准备联系。它不替网站确认编辑承诺、受众数据或商业条款。分类网站的目的，是把下一步问题问对，而不是快速生成一个没有范围的排行榜。",
          "Record website role, reader task, relevant work, proposed placement, region, source date, public contact route and unresolved questions. Label audience data by source and coverage instead of turning estimates into audited results. Unrelated personal information is unnecessary.\n\nIn an editorial hypothetical, a tutorial site and a code site may both generate visits, but the current brand task is explaining complex installation. Research which can supply that explanation and which information and work it needs, rather than choosing only by aggregate traffic.\n\nQuickKOL can help interpret the content job, research relevant creator work and prepare contact. It does not confirm editorial commitments, audience data or commercial terms for a website. Classification improves the next question instead of producing a quick ranking without a defined scope. The result can be a focused invitation, a request for specific evidence or a reason the current website model does not match the assignment."
