    "title": [
      "达人折扣码：把消费者优惠与归因规则分开",
      "Influencer Discount Codes: Separate Offers and Attribution"
    ],
    "summary": [
      "将达人折扣码拆成消费者优惠、合作归因与最终结算三层，设计清楚的条件、传播和异常处理记录。",
      "Separate influencer discount codes into customer offers, partner attribution and settlement, with clear conditions, distribution and exception records."
    ],
    "metaDescription": [
      "达人折扣码指南：明确适用商品、地区、期限与叠加规则，核对代码和点击归因及退款状态，不把代码订单当作增量证明。",
      "Plan influencer discount codes with product, territory, expiry and stacking conditions, then verify attribution and refunds without claiming incremental sales."
    ],
    "answer": [
      "Influencer discount codes同时可能涉及消费者优惠、合作方归因和佣金结算，但三层不是同一条规则。先说明谁在什么条件下得到什么优惠，再确认系统怎样分配记录、合同怎样批准佣金。代码被使用不证明购买者看过创作者内容，也不证明全部订单由该合作新增。品牌应保留优惠版本、传播路径、适用条件和交易状态，让消费者能理解，合作方能核对，团队能解释结果。",
      "Influencer discount codes can involve a customer offer, partner attribution and commission settlement, but these are three different rule layers. First specify who receives what offer under which conditions, then establish how records are credited and commissions approved. Code use does not prove that a purchaser saw the creator’s content or that every order was incremental to the collaboration. Retain offer version, distribution route, conditions and transaction state so customers can understand the offer, partners can review their records and the team can explain results. A short code is a useful access or recording mechanism, not a complete account of the customer journey."
    ],
